				std::stringstream body;

				{
					TextXmlWriter writer(body);
					XmlElement root(Name::declare("report", -1));
					root.addAttribute(Name::declare("userID", -1), r.submitterID);

					root.addChild(new XmlElement(Name::declare("comment", -1), r.comment));
